<?php
require_once dirname(__DIR__).'/includes/auth.php';require_role('administrator');
$search=trim((string)($_GET['q']??''));$where=["r.name='supervisor'"];$params=[];
if($search!==''){$where[]='(u.first_name LIKE ? OR u.last_name LIKE ? OR u.staff_number LIKE ? OR d.name LIKE ?)';$term='%'.$search.'%';array_push($params,$term,$term,$term,$term);}
$q=db()->prepare('SELECT u.id,u.first_name,u.last_name,u.staff_number,u.email,u.account_status,d.name department,f.name faculty,(SELECT COUNT(*) FROM student_supervisors ss WHERE ss.supervisor_id=u.id AND ss.ended_at IS NULL) assigned_students,(SELECT COUNT(*) FROM project_supervisors ps WHERE ps.supervisor_id=u.id AND ps.ended_at IS NULL) assigned_projects FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN departments d ON d.id=u.department_id LEFT JOIN faculties f ON f.id=d.faculty_id WHERE '.implode(' AND ',$where).' ORDER BY d.name,u.last_name,u.first_name LIMIT 500');$q->execute($params);$rows=$q->fetchAll();$pageTitle='Supervisor Management';$crumbTrail=['Admin','Supervisors Registry'];require dirname(__DIR__).'/includes/header.php';
?>
<section class="card filter-bar mb-3"><form method="get" class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input class="form-control" id="q" name="q" value="<?= e($search) ?>" placeholder="Search by name, staff number or department..." aria-label="Search supervisors"></label><button class="btn btn-primary btn-sm">Search</button><?php if($search!==''): ?><a class="btn btn-outline-primary btn-sm" href="<?= e(url('admin/supervisors.php')) ?>">Clear</a><?php endif; ?><a class="btn btn-danger btn-sm ms-auto" href="<?= e(url('admin/users.php')) ?>">Add Supervisor</a></form></section>
<section class="card p-4"><div class="section-row mb-3"><h2 class="section-heading mb-0">Academic Supervisor Registry</h2><span class="text-muted small">Showing <?= count($rows) ?> staff record<?= count($rows)===1?'':'s' ?></span></div><div class="table-responsive"><table class="table table-soft"><thead><tr><th>Supervisor name</th><th>Email address</th><th>Department</th><th>Students</th><th>Active projects</th><th>Status</th></tr></thead><tbody>
<?php foreach($rows as $r): $nm=trim(($r['first_name']??'').' '.($r['last_name']??'')); ?><tr><td><div class="person"><span class="person-avatar"><?= e(ui_initials($nm?:'S')) ?></span><div><strong><?= e($nm) ?></strong><small><?= e($r['staff_number']??'—') ?></small></div></div></td><td class="text-muted"><?= e($r['email']??'—') ?></td><td><?= e($r['department']??'Department pending') ?><br><small class="text-muted"><?= e($r['faculty']??'—') ?></small></td><td><?= (int)$r['assigned_students'] ?> assigned</td><td><?= (int)$r['assigned_projects'] ?> active</td><td><?= status_badge($r['account_status']) ?></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="6"><div class="empty-state">No supervisors match this search.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
